declare_lint ! { # [doc = " The `impl_trait_overcaptures` lint warns against cases where lifetime"] # [doc = " capture behavior will differ in edition 2024."] # [doc = ""] # [doc = " In the 2024 edition, `impl Trait`s will capture all lifetimes in scope,"] # [doc = " rather than just the lifetimes that are mentioned in the bounds of the type."] # [doc = " Often these sets are equal, but if not, it means that the `impl Trait` may"] # [doc = " cause erroneous borrow-checker errors."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,compile_fail,edition2021"] # [doc = " # #![deny(impl_trait_overcaptures)]"] # [doc = " # use std::fmt::Display;"] # [doc = " let mut x = vec![];"] # [doc = " x.push(1);"] # [doc = ""] # [doc = " fn test(x: &Vec<i32>) -> impl Display {"] # [doc = "     x[0]"] # [doc = " }"] # [doc = ""] # [doc = " let element = test(&x);"] # [doc = " x.push(2);"] # [doc = " println!(\"{element}\");"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " In edition < 2024, the returned `impl Display` doesn't capture the"] # [doc = " lifetime from the `&Vec<i32>`, so the vector can be mutably borrowed"] # [doc = " while the `impl Display` is live."] # [doc = ""] # [doc = " To fix this, we can explicitly state that the `impl Display` doesn't"] # [doc = " capture any lifetimes, using `impl Display + use<>`."] pub IMPL_TRAIT_OVERCAPTURES , Allow , "`impl Trait` will capture more lifetimes than possibly intended in edition 2024" , @ future_incompatible = FutureIncompatibleInfo { reason : FutureIncompatibilityReason :: EditionSemanticsChange (Edition :: Edition2024) , reference : "<https://doc.rust-lang.org/edition-guide/rust-2024/rpit-lifetime-capture.html>" , } ; }